CREATE TABLE IF NOT EXISTS returns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(190) NOT NULL,description TEXT NULL,evidence JSON NULL,status ENUM('requested','approved','rejected','received','inspected','refunded','closed') NOT NULL DEFAULT 'requested',refund_method ENUM('original_payment','wallet') NULL,refund_amount DECIMAL(14,2) NOT NULL DEFAULT 0,requested_at TIMESTAMP NULL,approved_at TIMESTAMP NULL,refunded_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY returns_user(user_id,created_at),KEY returns_order(order_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS return_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_id BIGINT UNSIGNED NOT NULL,order_item_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(12,3) NOT NULL,reason VARCHAR(190) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY return_items_return(return_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS refund_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_id BIGINT UNSIGNED NOT NULL,method ENUM('original_payment','wallet') NOT NULL,amount DECIMAL(14,2) NOT NULL,status ENUM('pending','processed','failed') NOT NULL DEFAULT 'pending',provider_reference VARCHAR(190) NULL,processed_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY refund_return(return_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
